-- Q1 Ventas confirmadas
SELECT count(*) FROM sale_order WHERE state IN ('sale','done');
-- Q2 Cotizaciones
SELECT count(*) FROM sale_order WHERE state IN ('draft','sent');
-- Q3 Empleados activos
SELECT count(*) FROM hr_employee WHERE active;
-- Q4 Cargos
SELECT count(*) FROM hr_job;
-- Q5 Departamentos activos
SELECT count(*) FROM hr_department WHERE active;
-- Q6 Compras con factura de proveedor publicada
SELECT count(DISTINCT pol.order_id)
FROM account_move_line aml
JOIN purchase_order_line pol ON pol.id = aml.purchase_line_id
JOIN account_move m ON m.id = aml.move_id
WHERE m.move_type = 'in_invoice' AND m.state = 'posted';
-- Q7 Materiales (comprables y no vendibles)
SELECT count(*) FROM product_template
WHERE active AND purchase_ok AND NOT sale_ok;
-- Q8 Facturas de cliente publicadas
SELECT count(*) FROM account_move
WHERE move_type = 'out_invoice' AND state = 'posted';
-- Q9 Documentos de respaldo
SELECT count(*) FROM ir_attachment
WHERE res_model = 'purchase.order' AND name LIKE 'I1-Respaldo-%';
